@file:Suppress("unused")import org.gradle.kotlin.dsl.DependencyHandlerScopeimport org.gradle.kotlin.dsl.PluginDependenciesSpecScopeimport utils.BomScopeinfix fun PluginDependenciesSpecScope.notate(plugin: Plugin) {	id(plugin.project).version(plugin.version).apply(false)}infix fun PluginDependenciesSpecScope.apply(plugin: Plugin) {	id(plugin.project).apply(true)}infix fun DependencyHandlerScope.dependency(dependency: Dependency) {	add("implementation", dependency.dependencyNotation)}fun DependencyHandlerScope.bom(dependency: Dependency, scopeBlock: BomScope.() -> Unit) {	add("implementation",platform(dependency.dependencyNotation))	val scope = BomScope(this)	scopeBlock(scope)}fun DependencyHandlerScope.loggingDependency() {	dependency(Github.Oshai.KotlinLoggingJvm)	dependency(Github.Slf4j.Slf4jSimple)}